export const LANGS = [
  { code: "EN", id: "en", label: "English" },
  { code: "FR", id: "fr", label: "Français" },
  { code: "AR", id: "ar", label: "العربية" },
  { code: "DE", id: "de", label: "Deutsch" }
];

export function t(lang, s) {
  if (!s || lang === "en") return s;
  const table = T[lang];
  if (!table) return s;
  const key = s.trim();
  const hit = table[key];
  if (!hit) return s;
  return s.replace(key, hit);
}
